    /**
     * Tests creating a new ClinicalOrder.
     *
     * @return    ClinicalOrder
     */
    public ClinicalOrder testCreate() throws Throwable {
    ClinicalOrder entity = null;

    LOGGER.info( "ClinicalOrderTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a ClinicalOrder");

    StringBuilder msg = new StringBuilder( "-- Failed to create a ClinicalOrder" );

    try {
        entity = service.createClinicalOrder( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getClinicalOrderId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a ClinicalOrder with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

