    /**
     * Tests getting all ClinicalOrders.
     *
     * @return    Collection
     */
    public List<ClinicalOrder> testGetAll() throws Throwable {
    LOGGER.info( "ClinicalOrderTest:testGetAll() - Retrieving Collection of ClinicalOrders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ClinicalOrder : " );
    List<ClinicalOrder> collection  = null;

    try {
        // call the static get method on the ClinicalOrderService
        collection = service.getAllClinicalOrder();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ClinicalOrder currEntity  = null;
            Iterator<ClinicalOrder> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getClinicalOrderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

